"""Compact post-hoc reporting; never modifies requests, predictions, or model."""
import json,hashlib,statistics,math
from pathlib import Path
P=Path(__file__).resolve().parent.parent/'results/finance'
scores=json.loads((P/'scores.json').read_text());meta=json.loads((P/'run_metadata.json').read_text());rows=[json.loads(s) for s in (P/'predictions.jsonl').read_text().splitlines()]
def percentile(values,p):
 values=sorted(values);i=(len(values)-1)*p;a=int(i);return values[a]*(1-(i-a))+values[min(a+1,len(values)-1)]*(i-a)
def wilson(k,n,z=1.959963984540054):
 p=k/n;d=1+z*z/n;c=(p+z*z/(2*n))/d;r=z*math.sqrt(p*(1-p)/n+z*z/(4*n*n))/d;return[c-r,c+r]
summary={'status':meta['status'],'model':meta['model'],'revision':meta['revision'],'mode':meta['mode'],'counts':scores['counts'],'splits':{},'paired_all_planned':scores['paired_all_planned'],'abstention':scores['abstention'],'mispredictions':[{k:x[k] for k in ['id','split','category','expected','prediction','max_probability']} for x in scores['case_results'] if not x['correct']],'runtime':{'started_at':meta['started_at'],'completed_at':meta['completed_at'],'load_seconds':meta['load_seconds'],'warmup_seconds':meta['warmup']['inference_seconds'],'forward_latency_seconds':{'median':statistics.median(x['inference_seconds'] for x in rows),'p95':percentile([x['inference_seconds'] for x in rows],.95),'sum':sum(x['inference_seconds'] for x in rows)},'input_token_range':[min(x['input_tokens'] for x in rows),max(x['input_tokens'] for x in rows)],'any_truncated':any(x['truncated'] for x in rows),'peak_process_rss_bytes':meta['max_rss_bytes'],'peak_process_rss_gib':meta['max_rss_bytes']/1024**3,'repeatability_probe':meta['repeatability_probe']},'hashes':{'requests':meta['requests_sha256'],'predictions':hashlib.sha256((P/'predictions.jsonl').read_bytes()).hexdigest(),'runner':meta['runner_sha256'],'finance_scorer':hashlib.sha256((P.parent.parent/'finance_benchmark/score.py').read_bytes()).hexdigest()},'limitations':['Freshly authored synthetic pilot, not a representative production sample or public German standard benchmark','Only experimental CPU NF4 Clef-flash tested; no stock BF16 or larger Clef run','All schemas are single-question choice; no noul, score, joint multi-field, vision or video test','Wilson interval is descriptive binomial uncertainty under iid assumptions; synthetic purposive design does not establish population representativeness','Small purposive 20-case language pairs cannot establish general language equivalence','Uncalibrated probabilities can be high on mistakes; no threshold was tuned on this test set']}
for split,details in scores['splits'].items():
 cases=[c for c in scores['case_results'] if c['split']==split];correct=sum(c['correct'] for c in cases)
 data={k:v for k,v in details.items() if k!='per_category'};data['correct']=correct;data['descriptive_wilson_95']=wilson(correct,len(cases));data['schema_valid']=sum(c['schema_valid'] for c in cases);data['mean_brier_sum']=statistics.mean(c['brier'] for c in cases);data['mean_nll']=statistics.mean(c['nll'] for c in cases);data['latency_seconds']={'median':statistics.median(c['latency_ms']/1000 for c in cases),'p95':percentile([c['latency_ms']/1000 for c in cases],.95)};data['categories']={k:{key:v[key] for key in ['n_planned','strict_accuracy_all_planned','macro_f1']} for k,v in details['per_category'].items()};summary['splits'][split]=data
summary['macro_f1_scope_warning']=scores.get('macro_f1_scope_warning')
summary['interpretation_warning']=scores.get('interpretation_warning')
summary['limitations'].append('Finance/broker cases test fictional explicit routing rules, not investment advice, underwriting, real eligibility or legal/regulatory compliance')
(P/'summary.json').write_text(json.dumps(summary,ensure_ascii=False,indent=2)+'\n')
print(json.dumps({'splits':{k:{field:v[field] for field in ['correct','n_planned','strict_accuracy_all_planned','schema_valid','descriptive_wilson_95','latency_seconds']} for k,v in summary['splits'].items()},'runtime':summary['runtime']},indent=2))
